from typing import Dict, List, Tuple, Union
import ast

Number = Union[int, float]

def complement_after_clamp(x: Number) -> float:
    """
    Apply: clamp x to [0, 100], then return 100 - x.
    """
    x = float(x)
    if x < 0.0:
        x = 0.0
    elif x > 100.0:
        x = 100.0
    return 100.0 - x


def dict_to_clamped_list(d: Dict[Union[str, Tuple[int, int]], Number]) -> List[float]:
    """
    Convert { "(i, j)": val, ... } (or {(i, j): val, ...}) to a flat list ordered by (i, j),
    using the rule: result = 100 - clamp(val, 0, 100).
    """
    def parse_key(k: Union[str, Tuple[int, int]]) -> Tuple[int, int]:
        if isinstance(k, tuple) and len(k) == 2:
            i, j = k
            return int(i), int(j)
        if isinstance(k, str):
            tup = ast.literal_eval(k)
            if isinstance(tup, tuple) and len(tup) == 2:
                i, j = tup
                return int(i), int(j)
        raise ValueError(f"Unrecognized key format: {k!r}")

    items = [ (parse_key(k), complement_after_clamp(v)) for k, v in d.items() ]
    items.sort(key=lambda kv: (kv[0][0], kv[0][1]))  # row-major order
    return [val for _, val in items]


def text_to_clamped_list(s: str) -> List[float]:
    """
    Parse lines of '<index> <value>' and return a list ordered by index,
    using the rule: result = 100 - clamp(value, 0, 100).
    """
    pairs = []
    for line in s.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        idx_str, val_str = line.split(None, 1)
        pairs.append((int(idx_str), complement_after_clamp(float(val_str))))

    pairs.sort(key=lambda t: t[0])
    return [v for _, v in pairs]



from typing import Iterable, List, Tuple

def severity_tail_score(
    values: Iterable[float],
    cap: float = 100.0,      # L in the paper
    threshold: float = 20.0, # T in the paper
    alpha: float = 1.0,
    return_weights: bool = False
) -> float | Tuple[float, List[float]]:
    """
    Compute S = (1/N) * sum_i w_i, where
      w_i = max(0, (min(L, m_i) - T) / (L - T)) ** alpha

    Here each m_i is a *drop magnitude* in [0, 100], e.g. m_i = 100 - clamp(x_i, 0, 100).
    Pass in the *joined list* (e.g., dict_list + text_list).

    Args:
      values: iterable of drop magnitudes (floats).
      cap (L): worst-case cap as a percentage (default 100).
      threshold (T): tolerance as a percentage (default 20).
      alpha: tail-emphasis exponent (>=1), default 1.
      return_weights: if True, also return the list of w_i.

    Returns:
      S (and optionally the list of w_i if return_weights=True).
    """
    denom = cap - threshold
    if denom <= 0:
        raise ValueError("cap must be greater than threshold.")

    w: List[float] = []
    for v in values:
        m = max(0.0, float(v))             # ensure non-negative drop magnitude
        sev = max(0.0, (min(cap, m) - threshold) / denom)
        w.append(sev ** alpha)

    S = 0.0 if not w else sum(w) / len(w)
    return (S, w) if return_weights else S


